;; sorted maps and sets.
(println (sorted-map :b 2 :a 1 :c 3) (sorted-set 3 1 2 1) (sorted-map) (sorted-set))
(println (assoc (sorted-map 2 :b) 1 :a 3 :c) (dissoc (sorted-map 1 :a 2 :b) 1) (conj (sorted-set 5) 1 9) (disj (sorted-set 1 2 3) 2))
(println (get (sorted-map :a 1) :a) ((sorted-map :a 1) :a) ((sorted-map :a 1) :z :nf) ((sorted-set 1 2) 2) (:a (sorted-map :a 1)) (contains? (sorted-set 1) 1))
(println (= (sorted-map :a 1) {:a 1}) (= {:a 1} (sorted-map :a 1)) (= #{1 2} (sorted-set 2 1)) (= (sorted-map :a 1) (sorted-map :a 1)) (= (sorted-map :a 1) {:a 2}))
(println (= (hash (sorted-map :a 1 :b 2)) (hash {:b 2 :a 1})) (= (hash (sorted-set 1 2)) (hash #{2 1})))
(println (first (sorted-map 3 :c 1 :a)) (seq (sorted-map 3 :c 1 :a)) (keys (sorted-map 3 :c 1 :a)) (vals (sorted-map 3 :c 1 :a)) (rseq (sorted-set 1 2 3)) (rseq (sorted-map 1 :a 2 :b)))
(println (count (sorted-map 1 2 3 4)) (count (sorted-set 1 1 2)) (empty (sorted-map 1 2)) (sorted? (sorted-map)) (sorted? (sorted-set)) (sorted? {}) (sorted? [1]))
(println (into (sorted-map) {:z 1 :y 2 :x 3}) (into (sorted-set) [9 3 7 3]) (into (sorted-set) "hello") (apply sorted-set (range 10 0 -1)))
(println (map inc (sorted-set 3 1 2)) (reduce + (sorted-set 1 2 3)) (find (sorted-map 1 :a) 1) (last (sorted-map 1 :a 2 :b)) (nth (seq (sorted-set 5 6 7)) 1))
(println (sorted-map "b" 1 "a" 2) (sorted-set "pear" "apple") (sorted-set 1.5 1 2) (sorted-map [1 2] :v [1 1] :u) (sorted-set nil 1))
(println (subseq (sorted-set 1 2 3 4 5) > 2) (subseq (sorted-set 1 2 3 4 5) >= 2 < 4) (subseq (sorted-map 1 :a 2 :b 3 :c) <= 2))
(println (meta (with-meta (sorted-map 1 2) {:m 1})) (meta (conj (with-meta (sorted-set) {:m 1}) 3)))
(println (try (sorted-map :a 1 "b" 2) (catch Exception e (ex-message e))))
(println (try (conj (sorted-set 1) :kw) (catch Exception e (ex-message e))))
(println (try (sorted-set {:a 1}) (catch Exception e (ex-message e))))
(println (type (sorted-map)) (type (sorted-set)) (str (sorted-map :k "v")) (pr-str (sorted-set \a \b)))
(let [m (reduce (fn [m i] (assoc m (- 100 i) i)) (sorted-map) (range 50))]
  (println (count m) (take 3 (keys m)) (take 3 (rseq m)) (get m 51)))
(println (try (get (sorted-map 1 :a) "x") (catch Exception e (ex-message e))) (try (dissoc (sorted-map 1 :a) :k) (catch Exception e (ex-message e))) (get (sorted-map) {:a 1}) (get (sorted-map 1 :a) nil :nf))
(println (map? (sorted-map)) (set? (sorted-set)) (coll? (sorted-set)) (ifn? (sorted-map)) (associative? (sorted-map)))
(defmacro from-macro [] (sorted-map 3 :c 1 :a))
(println (from-macro) (sorted? (from-macro)))
